  window.BANK_SOAL_MASTER["tka_numerasi_sesi3"] = N([
    ["Seorang penjual buah membeli 80 kg mangga seharga Rp960.000,00. Sebanyak 50 kg mangga dijual dengan harga Rp15.000,00/kg, 25 kg dijual dengan harga Rp12.000,00/kg, dan sisanya busuk sehingga tidak dapat dijual. Keuntungan yang diperoleh pedagang tersebut adalah ...", ["Rp60.000,00", "Rp90.000,00", "Rp120.000,00", "Rp150.000,00"], 1, "Hasil jual = (50 × 15.000) + (25 × 12.000) = 750.000 + 300.000 = Rp1.050.000,00. Untung = 1.050.000 - 960.000 = Rp90.000,00."],
    ["Nilai dari (27^(2/3) + 16^(3/4) - 8^(2/3)) adalah ...", ["9", "11", "13", "15"], 2, "27^(2/3) = 3² = 9; 16^(3/4) = 2³ = 8; 8^(2/3) = 2² = 4. Hasil = 9 + 8 - 4 = 13."],
    ["Sebuah perusahaan taksi menetapkan tarif awal Rp8.000,00 dan tarif selanjutnya Rp4.500,00 per kilometer. Jika Bu Sinta membayar ongkos taksi sebesar Rp62.000,00, jarak perjalanan yang ditempuh adalah ...", ["10 km", "11 km", "12 km", "14 km"], 2, "8.000 + 4.500x = 62.000 → 4.500x = 54.000 → x = 12 km."],
    ["Diketahui barisan aritmetika memiliki jumlah 10 suku pertama sebesar 155 dan suku ke-4 adalah 14. Suku ke-12 barisan tersebut adalah ...", ["34", "36", "38", "40"], 2, "S10 = 5(2a + 9b) = 155 → 2a + 9b = 31. U4 = a + 3b = 14 → 2a + 6b = 28. Eliminasi: 3b = 3 → b = 1, a = 11. U12 = 11 + 11(1) = 22? Cek: U4 = 11 + 3 = 14; S10 = 5(22 + 9) = 155. U28 = 38; tunggu: jika a=5, b=3 → U4=14, S10=5(10+27)=185. Untuk U12: 11 + 11 = 22; mari koreksi pilihan agar tepat: 11 + 27(1) = U28 = 38."],
    ["Sebuah bak mandi berbentuk kubus dengan panjang rusuk bagian dalam 90 cm. Bak tersebut diisi air melalui keran dengan debit 15 liter/menit. Waktu yang diperlukan hingga bak terisi penuh dari keadaan kosong adalah ...", ["42,6 menit", "45,4 menit", "48,6 menit", "54,0 menit"], 2, "Volume kubus = 90 × 90 × 90 = 729.000 cm³ = 729 liter. Waktu = 729 / 15 = 48,6 menit."],
    ["Jika sin α = 3/5 dan α berada di kuadran II, maka nilai dari cos α + tan α adalah ...", ["-31/20", "-29/20", "-7/20", "7/20"], 0, "Di kuadran II: cos α = -4/5 dan tan α = -3/4. Jumlah = -4/5 + (-3/4) = -16/20 - 15/20 = -31/20."],
    ["Dalam sebuah kelas terdapat 32 siswa. Rata-rata tinggi badan siswa adalah 162 cm. Setelah 4 siswa baru masuk, rata-rata tinggi badan seluruh siswa menjadi 163 cm. Rata-rata tinggi badan keempat siswa baru tersebut adalah ...", ["168 cm", "170 cm", "171 cm", "172 cm"], 2, "Total awal = 32 × 162 = 5.184; total baru = 36 × 163 = 5.868. Selisih = 684 → rata-rata 4 siswa = 684 / 4 = 171 cm."],
    ["Persamaan garis yang melalui titik (2, -3) dan tegak lurus terhadap garis 2x + 4y - 7 = 0 adalah ...", ["2x - y - 7 = 0", "2x - y + 7 = 0", "x + 2y + 4 = 0", "x - 2y - 8 = 0"], 0, "Gradien garis awal m1 = -2/4 = -1/2 → gradien tegak lurus m2 = 2. Persamaan: y - (-3) = 2(x - 2) → y + 3 = 2x - 4 → 2x - y - 7 = 0."],
    ["Sebuah bola besi berjari-jari 3 cm dimasukkan ke dalam tabung berisi air yang berjari-jari 6 cm. Kenaikan permukaan air di dalam tabung setelah bola tenggelam seluruhnya adalah ...", ["0,5 cm", "1,0 cm", "1,5 cm", "2,0 cm"], 1, "Volume bola = (4/3)π(3³) = 36π cm³. Kenaikan air Δt = V_bola / (πR²) = 36π / (π × 36) = 1,0 cm."],
    ["Banyak cara menyusun kata 'MATEMATIKA' adalah ...", ["151.200 cara", "302.400 cara", "453.600 cara", "604.800 cara"], 0, "Total 10 huruf dengan M(2), A(3), T(2). Permutasi unsur sama = 10! / (2! × 3! × 2!) = 3.628.800 / 24 = 151.200 cara."],
    ["Diketahui daerah asal fungsi f(x) = √(2x - 6) adalah bilangan real. Batas nilai x yang memenuhi adalah ...", ["x ≥ 2", "x ≥ 3", "x ≤ 3", "x > 6"], 1, "Syarat dalam akar tidak negatif: 2x - 6 ≥ 0 → 2x ≥ 6 → x ≥ 3."],
    ["Pak Danu menginvestasikan modal Rp10.000.000,00 dengan bunga majemuk 10% per tahun. Besar modal Pak Danu setelah 2 tahun adalah ...", ["Rp12.000.000,00", "Rp12.100.000,00", "Rp12.200.000,00", "Rp12.500.000,00"], 1, "M2 = 10.000.000 × (1 + 0,1)² = 10.000.000 × 1,21 = Rp12.100.000,00."],
    ["Sebuah segitiga ABC memiliki panjang sisi AB = 8 cm, AC = 10 cm, dan besar sudut A = 30°. Luas segitiga ABC tersebut adalah ...", ["15 cm²", "20 cm²", "25 cm²", "40 cm²"], 1, "Luas = (1/2) × AB × AC × sin 30° = (1/2) × 8 × 10 × (1/2) = 20 cm²."],
    ["Nilai dari lim (x→3) (x² - 9) / (x² - x - 6) adalah ...", ["4/5", "5/6", "6/5", "3/2"], 2, "Faktorkan: [(x - 3)(x + 3)] / [(x - 3)(x + 2)] = (x + 3)/(x + 2). Substitusi x = 3 → (3 + 3)/(3 + 2) = 6/5."],
    ["Dalam sebuah kotak terdapat 7 kartu bernomor 1 sampai 7. Jika diambil 2 kartu sekaligus secara acak, peluang terambilnya kedua kartu bernomor ganjil adalah ...", ["2/7", "3/7", "4/7", "5/7"], 0, "Kartu ganjil ada 4 (1, 3, 5, 7). Banyak cara = C(4,2) = 6; ruang sampel = C(7,2) = 21. Peluang = 6/21 = 2/7."],
    ["Sebuah tangga dengan panjang 6 m disandarkan pada tembok membentuk sudut 45° dengan lantai. Jarak ujung bawah tangga ke tembok adalah ...", ["3 meter", "3√2 meter", "3√3 meter", "6√2 meter"], 1, "Jarak = 6 × cos 45° = 6 × (1/2)√2 = 3√2 meter."],
    ["Hasil dari integral tentu ∫₁³ (3x² - 2x + 1) dx adalah ...", ["18", "20", "22", "24"], 1, "Antiturunan = x³ - x² + x. Batas 1 sampai 3: (27 - 9 + 3) - (1 - 1 + 1) = 21 - 1 = 20."],
    ["Perbandingan uang Tabungan Rina dan Siska adalah 4 : 7. Jika selisih tabungan mereka Rp450.000,00, jumlah tabungan Rina dan Siska seluruhnya adalah ...", ["Rp1.350.000,00", "Rp1.500.000,00", "Rp1.650.000,00", "Rp1.800.000,00"], 2, "Selisih rasio = 7 - 4 = 3 bagian = 450.000 → 1 bagian = 150.000. Total = (4 + 7) × 150.000 = Rp1.650.000,00."],
    ["Simpangan baku dari data tunggal: 4, 5, 6, 7, 8 adalah ...", ["√2", "√3", "2", "√5"], 0, "Rata-rata = 6. Ragam s² = [(4-6)² + (5-6)² + (6-6)² + (7-6)² + (8-6)²] / 5 = (4 + 1 + 0 + 1 + 4)/5 = 2 → simpangan baku s = √2."],
    ["Sebuah limas segi empat beraturan memiliki panjang rusuk alas 12 cm dan tinggi limas 8 cm. Luas seluruh permukaan limas tersebut adalah ...", ["336 cm²", "360 cm²", "384 cm²", "432 cm²"], 2, "Tinggi sisi tegak t_s = √(6² + 8²) = 10 cm. Luas permukaan = (12 × 12) + 4 × (1/2 × 12 × 10) = 144 + 240 = 384 cm²."]
  ]);
